after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def _student(last: str, first: str) -> Student:
    return Student("1", last, first, "A")

def _trio() -> list:
    return [
        _student("Halloway", "Juno"),
        _student("Dunmere", "Piet"),
        _student("Abbott", "Ora")
    ]

class SeatingTests(unittest.TestCase):
    def test_sorted_by_last_name_in_rows(self):
        expected = [
            "Row 1: Abbott, Ora | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ]
        self.assertEqual(seating_rows(_trio(), 2), expected)

    def test_first_name_breaks_ties(self):
        late_one = _student("Poe", "Zed")
        early_one = _student("Poe", "Al")
        self.assertEqual(
            seating_rows([late_one, early_one], 5),
            ["Row 1: Poe, Al | Poe, Zed"]
        )

    def test_bad_seat_counts_raise(self):
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(_trio(), seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
